var r=[{title:`Tre kategorier`,text:`Anti-extension hindrar ländryggen från att svanka för mycket, som i en planka eller en dead bug. Anti-rotation motstår vridning, som i en Pallof-press med ett säkert förankrat band. Anti-lateralflexion motstår sidoböjning, som i en sidoplanka eller en bärövning med en vikt i ena handen. Bukväggen, ryggmusklerna, diafragman och höfterna hjälper alla till att kontrollera bålen.`},{title:`Teknikexempel`,text:`I en underarmsplanka, rikta in revben och bäcken, tryck bort golvet genom armarna och fortsätt andas medan du håller dig stadig. I en dead bug, rör motsatt arm och ben bara så långt som bålen förblir kontrollerad. I en sidoplanka, håll en rak, stödd linje och låt inte höfterna sjunka.`},{title:`Progressioner`,text:`Börja med korta hållningar och korta hävarmar. En sidoplanka med stöd på knät kan komma före en hel sidoplanka, och en dead bug med böjda knän före sträckta ben. Gör det svårare genom att förlänga hävarmen, lägga till en måttlig belastning eller hålla längre under kontroll. Om din hållning brister har övningen blivit för svår. Håll koll på andning och uppriktning när du går vidare.`},{title:`Bortom plankor`,text:`Crunches och andra bålböjningsövningar tränar också magmusklerna, men de täcker inte alla bålens uppgifter. Rodd, knäböj och bärövningar får också bålen att arbeta för att hålla sig stabil. Du behöver inte träna alla riktningar i ett pass. Ta med några kontrollerade bålövningar under veckan, valda efter din erfarenhet och hur din ländrygg tål dem. Att göra dem regelbundet och gå framåt i en takt du tål betyder mer.`}];var t=[{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: grunder i säkerhet och styrketräning`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:r,sources:t};export{a as default,r as sections,t as sources};